using System.Security.Claims;
using Finora.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace Finora.Api.Features;

public sealed record AccountRequest(string Name, AccountType AccountType, string CurrencyCode, decimal InitialBalance);
public sealed record CategoryRequest(string Name, CategoryType CategoryType, string Icon, string Color);
public sealed record TransactionRequest(Guid AccountId, Guid? CategoryId, TransactionType TransactionType, decimal Amount, string Description, DateOnly TransactionDate, string? Notes);
public sealed record BudgetRequest(Guid CategoryId, decimal Amount, int Month, int Year);
public sealed record RecurringRequest(Guid AccountId, Guid? CategoryId, TransactionType TransactionType, decimal Amount, string Description, RecurringFrequency Frequency, DateOnly StartDate, DateOnly NextOccurrenceDate, DateOnly? EndDate, bool IsActive);
public sealed record MortgageRequest(string Name, string Lender, string? PropertyAddress, decimal OriginalPrincipal, decimal OutstandingBalance, decimal InterestRate, MortgageRateType RateType, decimal MonthlyPayment, string CurrencyCode, DateOnly StartDate, DateOnly EndDate, int PaymentDay);
public sealed record HouseholdBillRequest(string Name, string Provider, HouseholdBillType BillType, decimal Amount, string CurrencyCode, int BillingDay, DateOnly StartDate, DateOnly? EndDate, bool IsActive, bool IsRecurring = true);
public sealed record MedicalExpenseRequest(string Description, string Provider, MedicalExpenseType ExpenseType, decimal Amount, string CurrencyCode, DateOnly ExpenseDate, string? Notes, bool IsReimbursable);
public sealed record SupermarketExpenseRequest(string Store, string Description, SupermarketExpenseType ExpenseType, decimal Amount, string CurrencyCode, DateOnly ExpenseDate, string? Notes);
public sealed record PersonalExpenseRequest(PersonalExpenseArea Area, PersonalExpenseType ExpenseType, string Description, string Provider, decimal Amount, string CurrencyCode, DateOnly ExpenseDate, string? Notes);
public sealed record PetExpenseRequest(string PetName, string Description, string Provider, PetExpenseType ExpenseType, decimal Amount, string CurrencyCode, DateOnly ExpenseDate, string? Notes);
public sealed record FinancialProductRequest(string Name, string Institution, string? LastFourDigits, decimal CurrentBalance, decimal? CreditLimit, decimal? OriginalPrincipal, decimal? InterestRate, decimal? MonthlyPayment, int? PaymentDay, DateOnly? StartDate, DateOnly? EndDate, DateOnly? ExpiryDate, string CurrencyCode, bool IsActive, string? Notes);
public sealed record Page<T>(IReadOnlyList<T> Items, int PageNumber, int PageSize, int TotalCount);

public sealed class FinanceService(FinoraDbContext db)
{
    public static Guid UserId(ClaimsPrincipal user) => Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!);
    public Task<List<Account>> Accounts(Guid userId) => db.Accounts.AsNoTracking().Where(x => x.UserId == userId).OrderBy(x => x.Name).ToListAsync();
    public async Task<Account> CreateAccount(Guid userId, AccountRequest r) { if (string.IsNullOrWhiteSpace(r.Name) || r.CurrencyCode.Length != 3) throw new ArgumentException("Name and a three-letter currency are required."); var x = new Account { UserId=userId, Name=r.Name.Trim(), AccountType=r.AccountType, CurrencyCode=r.CurrencyCode.ToUpperInvariant(), InitialBalance=r.InitialBalance }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public Task<List<Category>> Categories(Guid userId) => db.Categories.AsNoTracking().Where(x => x.UserId == userId).OrderBy(x => x.Name).ToListAsync();
    public async Task<Category> CreateCategory(Guid userId, CategoryRequest r) { ValidateCategory(r); if(await db.Categories.AnyAsync(x=>x.UserId==userId&&x.Name.ToLower()==r.Name.Trim().ToLower()&&x.CategoryType==r.CategoryType))throw new ArgumentException("A category with this name and type already exists."); var x = new Category { UserId=userId, Name=r.Name.Trim(), CategoryType=r.CategoryType, Icon=r.Icon.Trim(), Color=r.Color.ToUpperInvariant() }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<Category> UpdateCategory(Guid userId,Guid id,CategoryRequest r) { ValidateCategory(r); var x=await db.Categories.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Category not found."); if(await db.Categories.AnyAsync(other=>other.Id!=id&&other.UserId==userId&&other.Name.ToLower()==r.Name.Trim().ToLower()&&other.CategoryType==r.CategoryType))throw new ArgumentException("A category with this name and type already exists."); x.Name=r.Name.Trim(); x.CategoryType=r.CategoryType; x.Icon=r.Icon.Trim(); x.Color=r.Color.ToUpperInvariant(); await db.SaveChangesAsync(); return x; }
    private static void ValidateCategory(CategoryRequest r) { if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.Icon))throw new ArgumentException("Name and icon are required."); if(!Enum.IsDefined(r.CategoryType))throw new ArgumentException("Category type is invalid."); if(r.Color?.Length!=7||r.Color[0]!='#'||!r.Color[1..].All(Uri.IsHexDigit))throw new ArgumentException("Color must be a six-digit hex value."); }
    public async Task<Page<Transaction>> Transactions(Guid userId, int page, int size, Guid? account, Guid? category, TransactionType? type, DateOnly? start, DateOnly? end, string? search) { var q=db.Transactions.AsNoTracking().Where(x=>x.UserId==userId); if(account.HasValue)q=q.Where(x=>x.AccountId==account); if(category.HasValue)q=q.Where(x=>x.CategoryId==category); if(type.HasValue)q=q.Where(x=>x.TransactionType==type); if(start.HasValue)q=q.Where(x=>x.TransactionDate>=start); if(end.HasValue)q=q.Where(x=>x.TransactionDate<=end); if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Description.Contains(search)); var count=await q.CountAsync(); var items=await q.OrderByDescending(x=>x.TransactionDate).Skip((page-1)*size).Take(size).ToListAsync(); return new(items,page,size,count); }
    public async Task<Transaction> CreateTransaction(Guid userId, TransactionRequest r) { if(r.Amount<=0)throw new ArgumentException("Amount must be positive."); if(!await db.Accounts.AnyAsync(x=>x.Id==r.AccountId&&x.UserId==userId))throw new KeyNotFoundException("Account not found."); if(r.CategoryId.HasValue&&!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId&&x.UserId==userId))throw new KeyNotFoundException("Category not found."); var x=new Transaction { UserId=userId, AccountId=r.AccountId, CategoryId=r.CategoryId, TransactionType=r.TransactionType, Amount=r.Amount, Description=r.Description.Trim(), TransactionDate=r.TransactionDate, Notes=r.Notes }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public Task<List<Budget>> Budgets(Guid userId) => db.Budgets.AsNoTracking().Where(x=>x.UserId==userId).ToListAsync();
    public async Task<Budget> CreateBudget(Guid userId, BudgetRequest r) { await ValidateBudget(userId,r); if(await db.Budgets.AnyAsync(x=>x.UserId==userId&&x.CategoryId==r.CategoryId&&x.Month==r.Month&&x.Year==r.Year))throw new ArgumentException("A budget already exists for this category and month."); var x=new Budget { UserId=userId, CategoryId=r.CategoryId, Amount=r.Amount, Month=r.Month, Year=r.Year }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<Budget> UpdateBudget(Guid userId,Guid id,BudgetRequest r) { await ValidateBudget(userId,r); var x=await db.Budgets.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Budget not found."); if(await db.Budgets.AnyAsync(other=>other.Id!=id&&other.UserId==userId&&other.CategoryId==r.CategoryId&&other.Month==r.Month&&other.Year==r.Year))throw new ArgumentException("A budget already exists for this category and month."); x.CategoryId=r.CategoryId; x.Amount=r.Amount; x.Month=r.Month; x.Year=r.Year; x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    private async Task ValidateBudget(Guid userId,BudgetRequest r) { if(r.Amount<=0||r.Month is <1 or >12||r.Year is <2000 or >2200)throw new ArgumentException("Budget amount or period is invalid."); if(!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId&&x.UserId==userId&&x.CategoryType==CategoryType.Expense))throw new KeyNotFoundException("Expense category not found."); }
    public Task<List<RecurringTransaction>> Recurring(Guid userId) => db.RecurringTransactions.AsNoTracking().Where(x=>x.UserId==userId).ToListAsync();
    public async Task<RecurringTransaction> CreateRecurring(Guid userId, RecurringRequest r) { if(r.Amount<=0)throw new ArgumentException("Amount must be positive."); if(!await db.Accounts.AnyAsync(x=>x.Id==r.AccountId&&x.UserId==userId))throw new KeyNotFoundException("Account not found."); var x=new RecurringTransaction { UserId=userId, AccountId=r.AccountId, CategoryId=r.CategoryId, TransactionType=r.TransactionType, Amount=r.Amount, Description=r.Description, Frequency=r.Frequency, StartDate=r.StartDate, NextOccurrenceDate=r.NextOccurrenceDate, EndDate=r.EndDate, IsActive=r.IsActive }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public Task<List<Mortgage>> Mortgages(Guid userId) => db.Mortgages.AsNoTracking().Where(x => x.UserId == userId).OrderBy(x => x.EndDate).ToListAsync();
    public async Task<Mortgage> CreateMortgage(Guid userId, MortgageRequest r) { if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.Lender))throw new ArgumentException("Name and lender are required."); if(r.OriginalPrincipal<=0||r.OutstandingBalance<0||r.OutstandingBalance>r.OriginalPrincipal)throw new ArgumentException("Outstanding balance must be between zero and the original principal."); if(r.InterestRate<0||r.InterestRate>100||r.MonthlyPayment<=0)throw new ArgumentException("Interest rate and monthly payment are invalid."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.EndDate<=r.StartDate)throw new ArgumentException("End date must be after the start date."); if(r.PaymentDay is <1 or >31)throw new ArgumentException("Payment day must be between 1 and 31."); var x=new Mortgage { UserId=userId, Name=r.Name.Trim(), Lender=r.Lender.Trim(), PropertyAddress=string.IsNullOrWhiteSpace(r.PropertyAddress)?null:r.PropertyAddress.Trim(), OriginalPrincipal=r.OriginalPrincipal, OutstandingBalance=r.OutstandingBalance, InterestRate=r.InterestRate, RateType=r.RateType, MonthlyPayment=r.MonthlyPayment, CurrencyCode=r.CurrencyCode.ToUpperInvariant(), StartDate=r.StartDate, EndDate=r.EndDate, PaymentDay=r.PaymentDay }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<Mortgage> UpdateMortgage(Guid userId, Guid id, MortgageRequest r) { if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.Lender))throw new ArgumentException("Name and lender are required."); if(r.OriginalPrincipal<=0||r.OutstandingBalance<0||r.OutstandingBalance>r.OriginalPrincipal)throw new ArgumentException("Outstanding balance must be between zero and the original principal."); if(r.InterestRate<0||r.InterestRate>100||r.MonthlyPayment<=0)throw new ArgumentException("Interest rate and monthly payment are invalid."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.EndDate<=r.StartDate)throw new ArgumentException("End date must be after the start date."); if(r.PaymentDay is <1 or >31)throw new ArgumentException("Payment day must be between 1 and 31."); var x=await db.Mortgages.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Mortgage not found."); x.Name=r.Name.Trim(); x.Lender=r.Lender.Trim(); x.PropertyAddress=string.IsNullOrWhiteSpace(r.PropertyAddress)?null:r.PropertyAddress.Trim(); x.OriginalPrincipal=r.OriginalPrincipal; x.OutstandingBalance=r.OutstandingBalance; x.InterestRate=r.InterestRate; x.RateType=r.RateType; x.MonthlyPayment=r.MonthlyPayment; x.CurrencyCode=r.CurrencyCode.ToUpperInvariant(); x.StartDate=r.StartDate; x.EndDate=r.EndDate; x.PaymentDay=r.PaymentDay; x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    public Task<List<HouseholdBill>> HouseholdBills(Guid userId) => db.HouseholdBills.AsNoTracking().Where(x=>x.UserId==userId).OrderBy(x=>x.BillingDay).ThenBy(x=>x.Name).ToListAsync();
    public async Task<HouseholdBill> CreateHouseholdBill(Guid userId, HouseholdBillRequest r) { ValidateHouseholdBill(r); var x=new HouseholdBill { UserId=userId, Name=r.Name.Trim(), Provider=r.Provider.Trim(), BillType=r.BillType, Amount=r.Amount, CurrencyCode=r.CurrencyCode.ToUpperInvariant(), BillingDay=r.BillingDay, StartDate=r.StartDate, EndDate=r.EndDate, IsActive=r.IsActive, IsRecurring=r.IsRecurring }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<HouseholdBill> UpdateHouseholdBill(Guid userId,Guid id,HouseholdBillRequest r) { ValidateHouseholdBill(r); var x=await db.HouseholdBills.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Household bill not found."); x.Name=r.Name.Trim(); x.Provider=r.Provider.Trim(); x.BillType=r.BillType; x.Amount=r.Amount; x.CurrencyCode=r.CurrencyCode.ToUpperInvariant(); x.BillingDay=r.BillingDay; x.StartDate=r.StartDate; x.EndDate=r.EndDate; x.IsActive=r.IsActive; x.IsRecurring=r.IsRecurring; x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    private static void ValidateHouseholdBill(HouseholdBillRequest r) { if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.Provider))throw new ArgumentException("Name and provider are required."); if(!Enum.IsDefined(r.BillType))throw new ArgumentException("Bill type is invalid."); if(r.Amount<=0)throw new ArgumentException("Amount must be positive."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.BillingDay is <1 or >31)throw new ArgumentException("Billing day must be between 1 and 31."); if(r.EndDate.HasValue&&r.EndDate.Value<r.StartDate)throw new ArgumentException("End date cannot be before the start date."); }
    public Task<List<MedicalExpense>> MedicalExpenses(Guid userId) => db.MedicalExpenses.AsNoTracking().Where(x=>x.UserId==userId).OrderByDescending(x=>x.ExpenseDate).ThenBy(x=>x.Description).ToListAsync();
    public async Task<MedicalExpense> CreateMedicalExpense(Guid userId,MedicalExpenseRequest r) { ValidateMedicalExpense(r); var x=new MedicalExpense { UserId=userId, Description=r.Description.Trim(), Provider=r.Provider.Trim(), ExpenseType=r.ExpenseType, Amount=r.Amount, CurrencyCode=r.CurrencyCode.ToUpperInvariant(), ExpenseDate=r.ExpenseDate, Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim(), IsReimbursable=r.IsReimbursable }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<MedicalExpense> UpdateMedicalExpense(Guid userId,Guid id,MedicalExpenseRequest r) { ValidateMedicalExpense(r); var x=await db.MedicalExpenses.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Medical expense not found."); x.Description=r.Description.Trim(); x.Provider=r.Provider.Trim(); x.ExpenseType=r.ExpenseType; x.Amount=r.Amount; x.CurrencyCode=r.CurrencyCode.ToUpperInvariant(); x.ExpenseDate=r.ExpenseDate; x.Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim(); x.IsReimbursable=r.IsReimbursable; x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    private static void ValidateMedicalExpense(MedicalExpenseRequest r) { if(string.IsNullOrWhiteSpace(r.Description)||string.IsNullOrWhiteSpace(r.Provider))throw new ArgumentException("Description and provider are required."); if(!Enum.IsDefined(r.ExpenseType))throw new ArgumentException("Medical expense type is invalid."); if(r.Amount<=0)throw new ArgumentException("Amount must be positive."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.Notes?.Length>1000)throw new ArgumentException("Notes cannot exceed 1000 characters."); }
    public Task<List<SupermarketExpense>> SupermarketExpenses(Guid userId) => db.SupermarketExpenses.AsNoTracking().Where(x=>x.UserId==userId).OrderByDescending(x=>x.ExpenseDate).ThenBy(x=>x.Store).ToListAsync();
    public async Task<SupermarketExpense> CreateSupermarketExpense(Guid userId,SupermarketExpenseRequest r) { ValidateSupermarketExpense(r); var x=new SupermarketExpense { UserId=userId, Store=r.Store.Trim(), Description=r.Description.Trim(), ExpenseType=r.ExpenseType, Amount=r.Amount, CurrencyCode=r.CurrencyCode.ToUpperInvariant(), ExpenseDate=r.ExpenseDate, Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim() }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<SupermarketExpense> UpdateSupermarketExpense(Guid userId,Guid id,SupermarketExpenseRequest r) { ValidateSupermarketExpense(r); var x=await db.SupermarketExpenses.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Supermarket expense not found."); x.Store=r.Store.Trim(); x.Description=r.Description.Trim(); x.ExpenseType=r.ExpenseType; x.Amount=r.Amount; x.CurrencyCode=r.CurrencyCode.ToUpperInvariant(); x.ExpenseDate=r.ExpenseDate; x.Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim(); x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    private static void ValidateSupermarketExpense(SupermarketExpenseRequest r) { if(string.IsNullOrWhiteSpace(r.Store)||string.IsNullOrWhiteSpace(r.Description))throw new ArgumentException("Store and description are required."); if(!Enum.IsDefined(r.ExpenseType))throw new ArgumentException("Supermarket expense type is invalid."); if(r.Amount<=0)throw new ArgumentException("Amount must be positive."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.Notes?.Length>1000)throw new ArgumentException("Notes cannot exceed 1000 characters."); }
    public Task<List<PersonalExpense>> PersonalExpenses(Guid userId,PersonalExpenseArea area) => db.PersonalExpenses.AsNoTracking().Where(x=>x.UserId==userId&&x.Area==area).OrderByDescending(x=>x.ExpenseDate).ThenBy(x=>x.Description).ToListAsync();
    public async Task<PersonalExpense> CreatePersonalExpense(Guid userId,PersonalExpenseRequest r) { ValidatePersonalExpense(r); var x=new PersonalExpense { UserId=userId, Area=r.Area, ExpenseType=r.ExpenseType, Description=r.Description.Trim(), Provider=r.Provider.Trim(), Amount=r.Amount, CurrencyCode=r.CurrencyCode.ToUpperInvariant(), ExpenseDate=r.ExpenseDate, Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim() }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<PersonalExpense> UpdatePersonalExpense(Guid userId,Guid id,PersonalExpenseRequest r) { ValidatePersonalExpense(r); var x=await db.PersonalExpenses.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Personal expense not found."); x.Area=r.Area; x.ExpenseType=r.ExpenseType; x.Description=r.Description.Trim(); x.Provider=r.Provider.Trim(); x.Amount=r.Amount; x.CurrencyCode=r.CurrencyCode.ToUpperInvariant(); x.ExpenseDate=r.ExpenseDate; x.Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim(); x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    private static void ValidatePersonalExpense(PersonalExpenseRequest r) { if(!Enum.IsDefined(r.Area)||!Enum.IsDefined(r.ExpenseType))throw new ArgumentException("Expense area or type is invalid."); var education=r.ExpenseType is PersonalExpenseType.Course or PersonalExpenseType.Book or PersonalExpenseType.Tuition or PersonalExpenseType.Certification or PersonalExpenseType.EducationSupplies or PersonalExpenseType.Other; var entertainment=r.ExpenseType is PersonalExpenseType.Game or PersonalExpenseType.Movie or PersonalExpenseType.Streaming or PersonalExpenseType.Event or PersonalExpenseType.Hobby or PersonalExpenseType.Other; if((r.Area==PersonalExpenseArea.Education&&!education)||(r.Area==PersonalExpenseArea.Entertainment&&!entertainment))throw new ArgumentException("Expense type does not match its area."); if(string.IsNullOrWhiteSpace(r.Description)||string.IsNullOrWhiteSpace(r.Provider))throw new ArgumentException("Description and provider are required."); if(r.Amount<=0)throw new ArgumentException("Amount must be positive."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.Notes?.Length>1000)throw new ArgumentException("Notes cannot exceed 1000 characters."); }
    public Task<List<PetExpense>> PetExpenses(Guid userId) => db.PetExpenses.AsNoTracking().Where(x=>x.UserId==userId).OrderByDescending(x=>x.ExpenseDate).ThenBy(x=>x.PetName).ToListAsync();
    public async Task<PetExpense> CreatePetExpense(Guid userId,PetExpenseRequest r) { ValidatePetExpense(r); var x=new PetExpense { UserId=userId, PetName=r.PetName.Trim(), Description=r.Description.Trim(), Provider=r.Provider.Trim(), ExpenseType=r.ExpenseType, Amount=r.Amount, CurrencyCode=r.CurrencyCode.ToUpperInvariant(), ExpenseDate=r.ExpenseDate, Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim() }; db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<PetExpense> UpdatePetExpense(Guid userId,Guid id,PetExpenseRequest r) { ValidatePetExpense(r); var x=await db.PetExpenses.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId)??throw new KeyNotFoundException("Pet expense not found."); x.PetName=r.PetName.Trim(); x.Description=r.Description.Trim(); x.Provider=r.Provider.Trim(); x.ExpenseType=r.ExpenseType; x.Amount=r.Amount; x.CurrencyCode=r.CurrencyCode.ToUpperInvariant(); x.ExpenseDate=r.ExpenseDate; x.Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim(); x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    private static void ValidatePetExpense(PetExpenseRequest r) { if(string.IsNullOrWhiteSpace(r.PetName)||string.IsNullOrWhiteSpace(r.Description)||string.IsNullOrWhiteSpace(r.Provider))throw new ArgumentException("Pet name, description, and provider are required."); if(!Enum.IsDefined(r.ExpenseType))throw new ArgumentException("Pet expense type is invalid."); if(r.Amount<=0)throw new ArgumentException("Amount must be positive."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.Notes?.Length>1000)throw new ArgumentException("Notes cannot exceed 1000 characters."); }
    public Task<List<FinancialProduct>> FinancialProducts(Guid userId,FinancialProductType type) => db.FinancialProducts.AsNoTracking().Where(x=>x.UserId==userId&&x.ProductType==type).OrderBy(x=>x.Name).ToListAsync();
    public async Task<FinancialProduct> CreateFinancialProduct(Guid userId,FinancialProductType type,FinancialProductRequest r) { ValidateFinancialProduct(type,r); var x=new FinancialProduct { UserId=userId, ProductType=type }; ApplyFinancialProduct(x,r); db.Add(x); await db.SaveChangesAsync(); return x; }
    public async Task<FinancialProduct> UpdateFinancialProduct(Guid userId,Guid id,FinancialProductType type,FinancialProductRequest r) { ValidateFinancialProduct(type,r); var x=await db.FinancialProducts.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==userId&&x.ProductType==type)??throw new KeyNotFoundException("Financial product not found."); ApplyFinancialProduct(x,r); x.UpdatedAtUtc=DateTime.UtcNow; await db.SaveChangesAsync(); return x; }
    private static void ApplyFinancialProduct(FinancialProduct x,FinancialProductRequest r) { x.Name=r.Name.Trim(); x.Institution=r.Institution.Trim(); x.LastFourDigits=string.IsNullOrWhiteSpace(r.LastFourDigits)?null:r.LastFourDigits.Trim(); x.CurrentBalance=r.CurrentBalance; x.CreditLimit=r.CreditLimit; x.OriginalPrincipal=r.OriginalPrincipal; x.InterestRate=r.InterestRate; x.MonthlyPayment=r.MonthlyPayment; x.PaymentDay=r.PaymentDay; x.StartDate=r.StartDate; x.EndDate=r.EndDate; x.ExpiryDate=r.ExpiryDate; x.CurrencyCode=r.CurrencyCode.ToUpperInvariant(); x.IsActive=r.IsActive; x.Notes=string.IsNullOrWhiteSpace(r.Notes)?null:r.Notes.Trim(); }
    private static void ValidateFinancialProduct(FinancialProductType type,FinancialProductRequest r) { if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.Institution))throw new ArgumentException("Name and institution are required."); if(r.CurrencyCode?.Length!=3)throw new ArgumentException("A three-letter currency is required."); if(r.CurrentBalance<0)throw new ArgumentException("Current balance cannot be negative."); if(r.LastFourDigits is not null&&(r.LastFourDigits.Length!=4||!r.LastFourDigits.All(char.IsDigit)))throw new ArgumentException("Last four digits must contain four numbers."); if(r.Notes?.Length>1000)throw new ArgumentException("Notes cannot exceed 1000 characters."); if(type==FinancialProductType.Loan&&(r.OriginalPrincipal is null or <=0||r.MonthlyPayment is null or <=0||r.InterestRate is null or <0||r.PaymentDay is <1 or >31||!r.StartDate.HasValue||!r.EndDate.HasValue||r.EndDate<=r.StartDate||r.CurrentBalance>r.OriginalPrincipal))throw new ArgumentException("Loan principal, balance, rate, payment, dates, and payment day are invalid."); if(type==FinancialProductType.CreditCard&&(r.CreditLimit is null or <=0||r.CurrentBalance>r.CreditLimit||r.PaymentDay is <1 or >31))throw new ArgumentException("Credit limit, balance, or payment day is invalid."); if(type==FinancialProductType.Investment&&(r.OriginalPrincipal is null or <0||!r.StartDate.HasValue))throw new ArgumentException("Invested amount and investment date are required."); }
    public async Task<object> Dashboard(Guid userId,int month,int year) { if(month is <1 or >12)throw new ArgumentException("Invalid month."); var tx=await db.Transactions.AsNoTracking().Where(x=>x.UserId==userId&&x.TransactionDate.Month==month&&x.TransactionDate.Year==year).ToListAsync(); var income=tx.Where(x=>x.TransactionType==TransactionType.Income).Sum(x=>x.Amount); var transactionExpenses=tx.Where(x=>x.TransactionType==TransactionType.Expense).Sum(x=>x.Amount); var monthStart=new DateOnly(year,month,1); var monthEnd=monthStart.AddMonths(1).AddDays(-1); var mortgageExpenses=await db.Mortgages.AsNoTracking().Where(x=>x.UserId==userId&&x.StartDate<=monthEnd&&x.EndDate>=monthStart&&x.OutstandingBalance>0).SumAsync(x=>(decimal?)x.MonthlyPayment)??0; var householdBillExpenses=await db.HouseholdBills.AsNoTracking().Where(x=>x.UserId==userId&&x.IsActive&&x.StartDate<=monthEnd&&(!x.EndDate.HasValue||x.EndDate>=monthStart)).SumAsync(x=>(decimal?)x.Amount)??0; var medicalExpenses=await db.MedicalExpenses.AsNoTracking().Where(x=>x.UserId==userId&&x.ExpenseDate>=monthStart&&x.ExpenseDate<=monthEnd).SumAsync(x=>(decimal?)x.Amount)??0; var supermarketExpenses=await db.SupermarketExpenses.AsNoTracking().Where(x=>x.UserId==userId&&x.ExpenseDate>=monthStart&&x.ExpenseDate<=monthEnd).SumAsync(x=>(decimal?)x.Amount)??0; var petExpenses=await db.PetExpenses.AsNoTracking().Where(x=>x.UserId==userId&&x.ExpenseDate>=monthStart&&x.ExpenseDate<=monthEnd).SumAsync(x=>(decimal?)x.Amount)??0; var personalExpenses=await db.PersonalExpenses.AsNoTracking().Where(x=>x.UserId==userId&&x.ExpenseDate>=monthStart&&x.ExpenseDate<=monthEnd).GroupBy(x=>x.Area).Select(g=>new {area=g.Key,amount=g.Sum(x=>x.Amount)}).ToListAsync(); var educationExpenses=personalExpenses.FirstOrDefault(x=>x.area==PersonalExpenseArea.Education)?.amount??0; var entertainmentExpenses=personalExpenses.FirstOrDefault(x=>x.area==PersonalExpenseArea.Entertainment)?.amount??0; var expenses=transactionExpenses+mortgageExpenses+householdBillExpenses+medicalExpenses+supermarketExpenses+educationExpenses+entertainmentExpenses+petExpenses; var budgets=await db.Budgets.Where(x=>x.UserId==userId&&x.Month==month&&x.Year==year).SumAsync(x=>(decimal?)x.Amount)??0; var initial=await db.Accounts.Where(x=>x.UserId==userId&&!x.IsArchived).SumAsync(x=>(decimal?)x.InitialBalance)??0; var categoryNames=await db.Categories.Where(x=>x.UserId==userId).ToDictionaryAsync(x=>x.Id,x=>x.Name); var spending=tx.Where(x=>x.TransactionType==TransactionType.Expense).GroupBy(x=>x.CategoryId).Select(g=>new { category=g.Key.HasValue&&categoryNames.TryGetValue(g.Key.Value,out var n)?n:"Uncategorized", amount=g.Sum(x=>x.Amount)}).ToList(); if(mortgageExpenses>0)spending.Add(new {category="Mortgage",amount=mortgageExpenses}); if(householdBillExpenses>0)spending.Add(new {category="Household bills",amount=householdBillExpenses}); if(medicalExpenses>0)spending.Add(new {category="Medical expenses",amount=medicalExpenses}); if(supermarketExpenses>0)spending.Add(new {category="Supermarket",amount=supermarketExpenses}); if(educationExpenses>0)spending.Add(new {category="Education",amount=educationExpenses}); if(entertainmentExpenses>0)spending.Add(new {category="Entertainment",amount=entertainmentExpenses}); if(petExpenses>0)spending.Add(new {category="Pets",amount=petExpenses}); return new { totalBalance=initial+income-expenses, monthlyIncome=income, monthlyExpenses=expenses, mortgageExpenses, householdBillExpenses, medicalExpenses, supermarketExpenses, educationExpenses, entertainmentExpenses, petExpenses, remainingBudget=budgets-expenses, recentTransactions=tx.OrderByDescending(x=>x.TransactionDate).Take(5), spendingByCategory=spending, cashFlow=new[]{new { month, year, income, expenses }} }; }
}
